function upgradeCheck(bool $ok,string $label): void { global $checks; if(!$ok) throw new RuntimeException('FAIL: '.$label); $checks++; }
function upgradeDenied(callable $call,string $label): void { try { $call(); } catch(DomainException) { upgradeCheck(true,$label); return; } throw new RuntimeException('FAIL: expected denial: '.$label); }
