    $find=fn(string $reference)=>$store->concernForActor($official['id'],$reference);
    $change=function(array $actor,string $ref,string $action,array $data=[]) use($store,$find) { $store->mutate($actor['id'],$action,$ref,$data,$find($ref)['version']); return $find($ref); };
    $original=$find($id);
    DatabaseMaintenance::initialize($test->connect());
