        upgradeCheck(in_array($expected,array_map(fn($r)=>$r['TABLE_NAME'].':'.$r['COLUMN_NAME'],$keys),true),'foreign key '.$expected);
    }
    try { $fixtures->invalidPayload($id); throw new RuntimeException('Invalid JSON accepted'); } catch(PDOException) { upgradeCheck(true,'database rejects invalid concern JSON'); }
    try { $fixtures->orphanNotification(); throw new RuntimeException('Orphan accepted'); } catch(PDOException) { upgradeCheck(true,'database rejects orphan notification'); }
    $receipt=$store->submitGuest(array_replace($report,['street'=>'mabini street']),'guest-match'); $duplicate=$receipt['reference'];
    $store->updateLocation($official['id'],(int)$location['id'],['name'=>'Renamed Purok','sortOrder'=>0]);
    $third=$store->submitGuest(array_replace($report,['street'=>'  MABINI  ST  ']),'guest-third')['reference'];
    upgradeCheck(count($store->relatedConcerns($official['id'],$id))===3,'recurrence normalizes abbreviations and survives Purok rename');
    upgradeCheck(count($store->possibleDuplicates($official['id'],$id))===2,'automatic duplicate suggestions');
    upgradeCheck($find($duplicate)['status']==='Submitted','suggestion never changes status');
