    upgradeDenied(fn()=>$store->dismissDuplicate($resident['id'],$id,['candidateId'=>$duplicate]),'reporter cannot dismiss duplicate');
    $store->dismissDuplicate($official['id'],$id,['candidateId'=>$duplicate]);
    upgradeCheck(!in_array($duplicate,array_column($store->possibleDuplicates($official['id'],$id),'id'),true),'dismissal hides pair');
    upgradeCheck(!in_array($id,array_column($store->possibleDuplicates($official['id'],$duplicate),'id'),true),'dismissal symmetric');
    upgradeDenied(fn()=>$store->dismissDuplicate($official['id'],$id,['candidateId'=>'missing']),'forged candidate rejected');
