    $change($official,$own,'assign',['team'=>'Maintenance crew']);
    $store->mutate($staff['id'],'accept_work',$own,[],null);
    $change($staff,$own,'start',$work); $change($staff,$own,'resolve',array_replace($work,['workStatus'=>'Fully repaired']));
    upgradeDenied(fn()=>$store->submitFeedback($staff['id'],$own,['rating'=>'5']),'personnel reporter cannot rate own work');
    $rules=$store->officialRules($official['id'],'Street Lighting','Exposed wiring','Sparks visible');
    upgradeCheck(count($rules)===3,'official library seeded separately');
    $guidance=$store->suggestions($report);
    $ruleData=['category'=>'Street Lighting','concernType'=>'Exposed wiring','keypoint'=>'Sparks visible','revision'=>ComplaintStore::ruleRevision($rules),
        'action1'=>'New first staff action','action2'=>'New second staff action','action3'=>'Inactive staff action','active1'=>'1','active2'=>'1'];
    upgradeDenied(fn()=>$store->saveOfficialRules($staff['id'],$ruleData),'personnel cannot edit official library');
    $store->saveOfficialRules($official['id'],$ruleData);
    upgradeDenied(fn()=>$store->saveOfficialRules($official['id'],$ruleData),'stale official library edit rejected');
    upgradeCheck($store->suggestions($report)===$guidance,'resident guidance unaffected');
    $weekly=$store->weeklyConcerns($official['id']);
    upgradeCheck($weekly['groups'][0]['actions']===['New first staff action','New second staff action'],'weekly actions use active database rules in order');
    $rules=$store->officialRules($official['id'],'Street Lighting','Exposed wiring','Sparks visible');
    $planData=['ruleId'=>(string)$rules[0]['id'],'ruleVersion'=>(string)$rules[0]['version'],'title'=>'Make wiring safe','notes'=>'Coordinate visit','team'=>'Maintenance crew','personnelId'=>$staff['id'],'targetDate'=>date('Y-m-d',time()+86400),'requestKey'=>str_repeat('c',64)];
    upgradeDenied(fn()=>$store->saveActionPlan($staff['id'],0,$planData),'personnel cannot create plan');
    upgradeDenied(fn()=>$store->saveActionPlan($official['id'],0,array_replace($planData,['team'=>'Sanitation team'])),'plan assignee team validated');
    upgradeDenied(fn()=>$store->saveActionPlan($official['id'],0,array_replace($planData,['ruleId'=>$rules[2]['id']])),'inactive solution rejected');
    $planId=$store->saveActionPlan($official['id'],0,$planData);
    upgradeDenied(fn()=>$store->saveActionPlan($official['id'],0,array_replace($planData,['ruleVersion'=>'1','requestKey'=>str_repeat('d',64)])),'changed selected solution rejected');
    upgradeCheck($store->saveActionPlan($official['id'],0,$planData)===$planId && $store->actionPlans($official['id'])['total']===1,'replayed create yields one action plan');
    $plan=$store->actionPlan($official['id'],$planId);
    upgradeCheck($plan['selected_solution']==='New first staff action' && $plan['status']==='Planned','plan snapshot and initial status');
    $planData+=['status'=>'Ongoing','version'=>'1'];
    $store->saveActionPlan($official['id'],$planId,$planData);
    upgradeDenied(fn()=>$store->saveActionPlan($official['id'],$planId,$planData),'stale plan edit denied');
    $planData['version']='2'; $planData['status']='Completed';
    upgradeDenied(fn()=>$store->saveActionPlan($official['id'],$planId,$planData),'completion outcome required');
    $planData['outcome']='Isolated fault and repaired wiring.'; $store->saveActionPlan($official['id'],$planId,$planData);
    upgradeCheck($store->actionPlan($official['id'],$planId)['completed_at']!==null && $store->actionPlans($official['id'],'Completed')['total']===1,'completed plan retained in history');
    $ruleData['revision']=ComplaintStore::ruleRevision($rules); $ruleData['action1']='Changed later'; $store->saveOfficialRules($official['id'],$ruleData);
    upgradeCheck($store->actionPlan($official['id'],$planId)['selected_solution']==='New first staff action','plan retains selected solution history after library edit');
    for($i=0;$i<24;$i++) $store->submitGuest(array_replace($report,['street'=>'Other road '.$i]),'paging-'.$i);
    $page1=$store->pagedConcerns($official['id'],['category'=>'Street Lighting'],1,10);
    $page2=$store->pagedConcerns($official['id'],['category'=>'Street Lighting'],2,10);
    upgradeCheck($page1['total']===28 && count($page1['items'])===10 && count($page2['items'])===10,'SQL total and bounded page sizes');
    upgradeCheck(!array_intersect(array_column($page1['items'],'id'),array_column($page2['items'],'id')),'SQL pages do not overlap');
    upgradeCheck($store->pagedConcerns($official['id'],[],999,10)['page']===3,'out of range page clamped');
    upgradeCheck($store->pagedConcerns($official['id'],['personnel'=>$staff['id'],'status'=>'Verified','priority'=>'Urgent','team'=>'Maintenance crew'])['total']===1,'combined personnel team priority status filters');
    upgradeCheck($store->pagedConcerns($resident['id'],[])['total']===1,'resident paging scope');
    upgradeCheck($store->pagedConcerns($resident['id'],['search'=>"' OR 1=1 --"])['total']===0,'prepared search handles injection text');
