    $public=json_encode($store->publicStatistics());
    foreach(['PRIVATE GATE','Mabini','Private Reporter','private feedback','example.test',$id] as $secret) upgradeCheck(!str_contains($public,$secret),'public aggregation excludes '.$secret);
    upgradeDenied(fn()=>$store->generateFullBackup($staff['id']),'full backup official only');
    $archive=$store->generateFullBackup($official['id']); $zip=new PharData($archive['path']);
    upgradeCheck(isset($zip['database.sql']) && isset($zip['RESTORE.txt']),'ZIP contains database and restore instructions');
    $sql=$zip['database.sql']->getContent();
    upgradeCheck(!str_contains($sql,$db->passwordHash($official['id'])) && str_contains($sql,'!reset-required'),'full backup excludes password hashes');
    $evidence=$store->evidenceRecord($official['id'],$find($id)['initialEvidenceId']);
    upgradeCheck(isset($zip[$evidence['file_path']]),'ZIP contains evidence');
    foreach(new RecursiveIteratorIterator($zip) as $entry) upgradeCheck(!preg_match('~(?:\.env|mail\.local|session|\.tmp|\.php)$~',$entry->getFilename()),'ZIP allowlist entry');
    $restoreName='maintainpro_test_'.bin2hex(random_bytes(8)); DatabaseMaintenance::create($restoreName);
    try {
        $restore=$test->connect(); $restore=br_database($restoreName); (new DatabaseTestFixtures($restore))->restoreBackup($sql);
        DatabaseMaintenance::initialize($restore); $restored=new ComplaintStore($restore);
        upgradeCheck(count($restored->state()['cases'])===28 && $restored->actionPlans($official['id'])['total']===1,'ZIP SQL restores concerns and plans');
        upgradeCheck($restored->track($duplicate,$receipt['trackingCode'],'restore')['reference']===$duplicate,'guest tracking survives restore');
        upgradeDenied(fn()=>$restored->login($official['email'],$password,'restore'),'old password invalid after credential-free restore');
    } finally { DatabaseMaintenance::dropTestDatabase($restoreName); }
    unset($zip); unlink($archive['path']); $archive=null;
    upgradeCheck($store->auditLogs($official['id'],['action'=>'full_backup_created'])['total']===1,'full backup audit');
    upgradeCheck($store->auditLogs($official['id'],['action'=>'resolution_feedback_submitted'])['total']===1,'feedback audit');
    $legacyId=bin2hex(random_bytes(16)); $fixtures->legacyEvidence($id,$legacyId,$png);
    upgradeCheck($store->legacyEvidence($resident['id'],$legacyId)===$png,'legacy image loads through single concern lookup');
    upgradeCheck($store->legacyEvidence($other['id'],$legacyId)===null,'legacy image lookup preserves authorization');
    $fixtures->removeOfficialRole(); upgradeCheck(!$store->needsSetup(),'setup latch prevents reactivation after all officials removed');
    upgradeDenied(fn()=>$store->setup(['name'=>'Second Official','email'=>'second@example.test','password'=>$password]),'setup never reopened');
    echo "PASS: $checks system upgrade, privacy, migration, pagination, planning, feedback and ZIP restoration checks.\n";
} finally { if($archive && is_file($archive['path'])) unlink($archive['path']); $test->drop(); }
